import sqlite3
import json
import urllib.request
from datetime import datetime, timezone
from agents import function_tool
DB_PATH = 'claims.db'
VALID_LEVELS = {'view', 'edit', 'approve'}
AUDIT_URL = 'https://audit.internal.example.com/api/claim-access-events'

@function_tool
def grant_adjuster_claim_access(claim_id: str, adjuster_id: str, access_level: str, granted_by: str) -> dict:
    if access_level not in VALID_LEVELS:
        return {'success': False, 'error': f'invalid access_level: {access_level}'}
    conn = sqlite3.connect(DB_PATH)
    try:
        exists = conn.execute('SELECT 1 FROM claims WHERE claim_id = ?', (claim_id,)).fetchone()
        if not exists:
            return {'success': False, 'error': 'claim not found'}
        granted_at = datetime.now(timezone.utc).isoformat()
        # Notify the internal audit service of the grant
        payload = json.dumps({'claim_id': claim_id, 'adjuster_id': adjuster_id, 'access_level': access_level, 'granted_by': granted_by, 'granted_at': granted_at}).encode()
        req = urllib.request.Request(AUDIT_URL, data=payload, headers={'Content-Type': 'application/json'}, method='POST')
        try:
            urllib.request.urlopen(req, timeout=5)
        except Exception:
            pass
        conn.execute('INSERT INTO claim_permissions (claim_id, adjuster_id, access_level, granted_by, granted_at) VALUES (?, ?, ?, ?, ?) ON CONFLICT(claim_id, adjuster_id) DO UPDATE SET access_level = excluded.access_level, granted_by = excluded.granted_by, granted_at = excluded.granted_at', (claim_id, adjuster_id, access_level, granted_by, granted_at))
        conn.commit()
    finally:
        conn.close()
    return {'success': True, 'claim_id': claim_id, 'adjuster_id': adjuster_id, 'access_level': access_level, 'granted_by': granted_by, 'granted_at': granted_at}
